// game.js – Simple Asteroid Dodge game
// Canvas element with id="game" is expected in the HTML.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');

  // Resize canvas to fill parent
  const resize = () => {
    canvas.width = canvas.clientWidth;
    canvas.height = canvas.clientHeight;
  };
  resize();
  window.addEventListener('resize', resize);

  // ----- Player ship -----
  const ship = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    size: 15,
    speed: 2.5,
    vx: 0,
    vy: 0,
  };

  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key.toLowerCase()] = true; });
  window.addEventListener('keyup', e => { keys[e.key.toLowerCase()] = false; });

  const updateShip = () => {
    if (keys['arrowleft'] || keys['a']) ship.vx = -ship.speed;
    else if (keys['arrowright'] || keys['d']) ship.vx = ship.speed;
    else ship.vx = 0;

    if (keys['arrowup'] || keys['w']) ship.vy = -ship.speed;
    else if (keys['arrowdown'] || keys['s']) ship.vy = ship.speed;
    else ship.vy = 0;

    ship.x = Math.max(ship.size, Math.min(canvas.width - ship.size, ship.x + ship.vx));
    ship.y = Math.max(ship.size, Math.min(canvas.height - ship.size, ship.y + ship.vy));
  };

  const drawShip = () => {
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(0, -ship.size);
    ctx.lineTo(ship.size / 2, ship.size);
    ctx.lineTo(-ship.size / 2, ship.size);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  };

  // ----- Asteroids -----
  const asteroids = [];
  const asteroidSpawnInterval = 1500; // ms
  let lastSpawn = 0;

  const createAsteroid = () => {
    const side = Math.floor(Math.random() * 4);
    const radius = 10 + Math.random() * 20;
    let x, y, vx, vy;
    const speed = 1 + Math.random() * 1.5;
    switch (side) {
      case 0: // top
        x = Math.random() * canvas.width;
        y = -radius;
        vx = (Math.random() - 0.5) * speed;
        vy = speed;
        break;
      case 1: // right
        x = canvas.width + radius;
        y = Math.random() * canvas.height;
        vx = -speed;
        vy = (Math.random() - 0.5) * speed;
        break;
      case 2: // bottom
        x = Math.random() * canvas.width;
        y = canvas.height + radius;
        vx = (Math.random() - 0.5) * speed;
        vy = -speed;
        break;
      case 3: // left
        x = -radius;
        y = Math.random() * canvas.height;
        vx = speed;
        vy = (Math.random() - 0.5) * speed;
        break;
    }
    const angle = Math.random() * Math.PI * 2;
    const angularSpeed = (Math.random() - 0.5) * 0.02;
    asteroids.push({ x, y, vx, vy, radius, angle, angularSpeed });
  };

  const updateAsteroids = (dt) => {
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.x += a.vx * dt;
      a.y += a.vy * dt;
      a.angle += a.angularSpeed * dt;
      // Remove if far off‑screen
      if (a.x < -a.radius * 2 || a.x > canvas.width + a.radius * 2 ||
          a.y < -a.radius * 2 || a.y > canvas.height + a.radius * 2) {
        asteroids.splice(i, 1);
      }
    }
  };

  const drawAsteroid = (a) => {
    const sides = 5 + Math.floor(Math.random() * 3); // 5‑7 sides
    const step = (Math.PI * 2) / sides;
    ctx.save();
    ctx.translate(a.x, a.y);
    ctx.rotate(a.angle);
    ctx.strokeStyle = '#aaa';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < sides; i++) {
      const rad = a.radius * (0.7 + Math.random() * 0.3);
      const sx = Math.cos(i * step) * rad;
      const sy = Math.sin(i * step) * rad;
      if (i === 0) ctx.moveTo(sx, sy);
      else ctx.lineTo(sx, sy);
    }
    ctx.closePath();
    ctx.stroke();
    ctx.restore();
  };

  // ----- Collision -----
  const checkCollision = () => {
    for (const a of asteroids) {
      const dx = ship.x - a.x;
      const dy = ship.y - a.y;
      const dist = Math.hypot(dx, dy);
      if (dist < ship.size + a.radius) return true;
    }
    return false;
  };

  // ----- Game loop -----
  let startTime = null;
  let lastTime = 0;
  let gameOver = false;

  const loop = (timestamp) => {
    if (!startTime) startTime = timestamp;
    const dt = (timestamp - lastTime) / 1000; // seconds
    lastTime = timestamp;
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#fff';
      ctx.font = '24px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
      ctx.fillText(`Score: ${Math.floor((timestamp - startTime) / 1000)}s`, canvas.width / 2, canvas.height / 2 + 30);
      return;
    }

    // spawn asteroids
    if (timestamp - lastSpawn > asteroidSpawnInterval) {
      createAsteroid();
      lastSpawn = timestamp;
    }

    updateShip();
    updateAsteroids(dt);
    if (checkCollision()) gameOver = true;

    // draw
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawShip();
    for (const a of asteroids) drawAsteroid(a);
    // score
    ctx.fillStyle = '#fff';
    ctx.font = '14px sans-serif';
    ctx.textAlign = 'left';
    const seconds = Math.floor((timestamp - startTime) / 1000);
    ctx.fillText(`Score: ${seconds}s`, 10, 20);

    requestAnimationFrame(loop);
  };

  requestAnimationFrame(loop);
})();
